function cdqPdfDriveIntentV2277(id,reader){
  const drive=cdqPdfDriveUrlV2275(id);
  if(!/Android/i.test(navigator.userAgent||''))return drive;

  const fileId=encodeURIComponent(String(id||''));
  const pref=String(reader||'ask').toLowerCase();

  let intent='intent://drive.google.com/file/d/'+fileId+
    '/view#Intent;scheme=https;action=android.intent.action.VIEW;type=application/pdf;';

  if(pref==='ilovepdf'){
    intent+='package=com.ilovepdf.www;';
  }else if(pref==='acrobat'){
    intent+='package=com.adobe.reader;';
  }
  // pref=ask : aucun package forcé => Android affiche les applications
  // compatibles installées et laisse l'utilisateur mémoriser son choix.

  intent+='end';
  return intent;
}

